import{_ as e,o as a,c as i,a2 as r}from"./chunks/framework.Cdp8-jB6.js";const g=JSON.parse('{"title":"/fly — Creative-direction gap analysis (post polish wave 2)","description":"","frontmatter":{},"headers":[],"relativePath":"guides/fly-cinematic-creative-gap-analysis.md","filePath":"guides/fly-cinematic-creative-gap-analysis.md"}'),s={name:"guides/fly-cinematic-creative-gap-analysis.md"};function o(n,t,d,l,h,c){return a(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="fly-—-creative-direction-gap-analysis-post-polish-wave-2" tabindex="-1">/fly — Creative-direction gap analysis (post polish wave 2) <a class="header-anchor" href="#fly-—-creative-direction-gap-analysis-post-polish-wave-2" aria-label="Permalink to &quot;/fly — Creative-direction gap analysis (post polish wave 2)&quot;">​</a></h1><p><em>Companion to fly-cinematic-creative-direction.md and the technical fly-cinematic-gap-analysis.md. Asks the same question the technical gap analysis asks — what does the current /fly do well, what does it miss — but through the director&#39;s-eye lens, not the renderer&#39;s.</em></p><p>Score model: ★★★ already present and good · ★★ present but compromised · ★ partial / accidental · ✗ absent.</p><hr><h2 id="section-by-section-scoring" tabindex="-1">Section-by-section scoring <a class="header-anchor" href="#section-by-section-scoring" aria-label="Permalink to &quot;Section-by-section scoring&quot;">​</a></h2><h3 id="§1-camera-angle-vocabulary" tabindex="-1">§1 Camera angle vocabulary <a class="header-anchor" href="#§1-camera-angle-vocabulary" aria-label="Permalink to &quot;§1 Camera angle vocabulary&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Angle</th><th style="text-align:right;">Score</th><th>Notes</th></tr></thead><tbody><tr><td>Three-quarter</td><td style="text-align:right;">★★★</td><td>Default cinematic framing — already the bread and butter at flyby.</td></tr><tr><td>Eye-level</td><td style="text-align:right;">★★</td><td>Cruise framing is roughly eye-level to the spacecraft. Honest, slightly bland.</td></tr><tr><td>Over-the-shoulder</td><td style="text-align:right;">★</td><td>Achieved accidentally when the spacecraft sprite/model occludes the body limb. Not framed deliberately as a Cassini-antenna-foreground composition.</td></tr><tr><td>Low-angle / worm&#39;s-eye</td><td style="text-align:right;">✗</td><td>Never used. The Endurance-from-below grammar would slot into a launch beat.</td></tr><tr><td>High-angle</td><td style="text-align:right;">✗</td><td>Never used. Could anchor the &quot;we are small&quot; reveal at outer-system departures.</td></tr><tr><td>Bird&#39;s eye / top-down</td><td style="text-align:right;">★★★</td><td>The 2D view IS top-down. Used for navigation, not emotion. Acceptable.</td></tr><tr><td>Dutch / canted</td><td style="text-align:right;">✗</td><td>Never. Would punctuate malfunction beats (the only mission with crisis is Apollo 13 in the catalog — could lean into it).</td></tr><tr><td>Profile</td><td style="text-align:right;">★</td><td>The cruise default sometimes lands as profile when the ship&#39;s velocity vector is parallel to the camera. Not deliberate.</td></tr><tr><td>POV</td><td style="text-align:right;">✗</td><td>No cockpit / instrument POV. Possible for landing beats (Eagle descent reference).</td></tr></tbody></table><p><strong>Gap of the section:</strong> the only deliberate angle is three-quarter at flyby. Everything else is the result of where the spacecraft happens to be. The creative guide&#39;s lesson: each angle communicates a specific emotion — using only three-quarter means every shot reads the same emotional register (composed, neutral, post-card).</p><h3 id="§2-distance-language" tabindex="-1">§2 Distance language <a class="header-anchor" href="#§2-distance-language" aria-label="Permalink to &quot;§2 Distance language&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Distance</th><th style="text-align:right;">Score</th><th>Notes</th></tr></thead><tbody><tr><td>Extreme wide</td><td style="text-align:right;">★</td><td>We have &quot;wide cruise&quot; but it&#39;s medium-wide, not the Pale-Blue-Dot register.</td></tr><tr><td>Wide</td><td style="text-align:right;">★★★</td><td>Cruise + arrival establish shots — already strong.</td></tr><tr><td>Medium</td><td style="text-align:right;">★★★</td><td>Default cinematic frame at flyby. Strong.</td></tr><tr><td>Close-up</td><td style="text-align:right;">★</td><td>Achieved at peak when ship sprite/model dominates the frame, but not as a deliberate &quot;instrument register&quot; beat.</td></tr><tr><td>Extreme close-up</td><td style="text-align:right;">✗</td><td>Never. The &quot;humanise the robot&quot; beat — Cassini antenna, RTG fin, instrument boom — doesn&#39;t exist.</td></tr></tbody></table><p><strong>Gap of the section:</strong> we never sit at the cosmic extreme-wide register that the Voyager Pale-Blue-Dot grammar inhabits, and we never descend to the instrument-register close-up that humanises the spacecraft. The frame is always at medium distance ± lerp wiggle.</p><h3 id="§3-motion-vocabulary" tabindex="-1">§3 Motion vocabulary <a class="header-anchor" href="#§3-motion-vocabulary" aria-label="Permalink to &quot;§3 Motion vocabulary&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Motion</th><th style="text-align:right;">Score</th><th>Notes</th></tr></thead><tbody><tr><td>Track / follow</td><td style="text-align:right;">★★★</td><td>Default in cruise and during flyby. The base motion.</td></tr><tr><td>Dolly push-in</td><td style="text-align:right;">★★</td><td>Auto-zoom from cruise → flyby is technically a push-in; pacing too fast, no held arrival.</td></tr><tr><td>Dolly pull-out</td><td style="text-align:right;">★</td><td>Auto-zoom from flyby → cruise is technically a pull-out; never given the slow-pace-and-hold treatment that the creative guide demands. No &quot;afterglow beat.&quot;</td></tr><tr><td>Static / locked-off</td><td style="text-align:right;">✗</td><td>The camera is <strong>always</strong> lerping. There is no moment in /fly where the camera holds for 6+ seconds. The discipline of stillness is absent.</td></tr><tr><td>Arc / orbit</td><td style="text-align:right;">★★</td><td>Used for cruise breathing — currently subtle.</td></tr><tr><td>Pan</td><td style="text-align:right;">✗</td><td>The composition transitions are dolly-based, not pan-based.</td></tr><tr><td>Tilt</td><td style="text-align:right;">✗</td><td>The composition transitions are dolly-based, not tilt-based.</td></tr><tr><td>Pedestal / boom</td><td style="text-align:right;">✗</td><td>Vertical translation never used. The &quot;elevator past the Endurance ring&quot; grammar.</td></tr><tr><td>Crane</td><td style="text-align:right;">✗</td><td>Bezier-curved farewell crane — never used.</td></tr><tr><td>Parallax / dolly zoom</td><td style="text-align:right;">✗</td><td>Never used. One-shot per mission could be the moment Saturn is first visible to Cassini, for example.</td></tr><tr><td>Handheld / shake</td><td style="text-align:right;">✗</td><td>Never used. Apollo 13 LEM-burn grammar — currently we have no failure or crisis beats to apply this to.</td></tr><tr><td>Whip pan / snap zoom</td><td style="text-align:right;">✗</td><td>Never used. Could punctuate the trans-planetary cuts (Jupiter → scrubber jump → Saturn).</td></tr></tbody></table><p><strong>Gap of the section:</strong> the camera moves with one verb — <strong>track, optionally lerping into / out of a composition.</strong> Every other motion verb in the cinema-lexicon is absent. The &quot;discipline of NOT moving&quot; is most conspicuously missing — there is no locked-off shot anywhere in /fly, ever.</p><h3 id="§4-transition-vocabulary" tabindex="-1">§4 Transition vocabulary <a class="header-anchor" href="#§4-transition-vocabulary" aria-label="Permalink to &quot;§4 Transition vocabulary&quot;">​</a></h3><p>We have one transition: <strong>continuous lerp.</strong> There are no cuts. There are no dissolves. There are no match cuts. There are no J-cuts. There are no sound bridges. The mission plays as one continuous shot from launch to arrival — Cuarón&#39;s <em>Gravity</em> opening, but accidental, and without the discipline that makes Cuarón&#39;s choice meaningful.</p><table tabindex="0"><thead><tr><th>Transition</th><th style="text-align:right;">Score</th><th>Notes</th></tr></thead><tbody><tr><td>Hard cut</td><td style="text-align:right;">✗</td><td>Never. The scrubber-jump is the closest thing to a cut, but unintentional.</td></tr><tr><td>Dissolve</td><td style="text-align:right;">✗</td><td>Never. The cruise → flyby auto-zoom is the closest, but as a lerp it doesn&#39;t read as a dissolve.</td></tr><tr><td>Match cut</td><td style="text-align:right;">✗</td><td>Never. The &quot;Earth limb match-cut to Saturn limb&quot; would be powerful at the start and end of Cassini&#39;s mission.</td></tr><tr><td>Motion match</td><td style="text-align:right;">✗</td><td>Irrelevant in a continuous shot.</td></tr><tr><td>J-cut / L-cut</td><td style="text-align:right;">✗</td><td>No sound-led editing. We have narration audio that bridges, but it&#39;s not edited cinematically.</td></tr><tr><td>Sound bridge</td><td style="text-align:right;">★</td><td>The continuous narration thread IS a sound bridge of sorts. Accidental rather than crafted.</td></tr><tr><td>Fade</td><td style="text-align:right;">✗</td><td>Never. Could mark act breaks (Cassini&#39;s outbound vs Saturn-resident phases).</td></tr></tbody></table><p><strong>Gap of the section:</strong> the absence of cuts is the deepest gap. &quot;Every cut is intentional&quot; is one of the three throne-of-glory principles. We have no cuts to be intentional about. Adding even one deliberate cut per mission act would change the cinematic register substantially.</p><h3 id="§5-per-moment-shot-grammar" tabindex="-1">§5 Per-moment shot grammar <a class="header-anchor" href="#§5-per-moment-shot-grammar" aria-label="Permalink to &quot;§5 Per-moment shot grammar&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Moment</th><th style="text-align:right;">Score</th><th>Notes</th></tr></thead><tbody><tr><td>Pre-launch / countdown</td><td style="text-align:right;">✗</td><td>No pre-launch beat. We start at launch. The &quot;weight of decades of work&quot; register doesn&#39;t exist.</td></tr><tr><td>Launch</td><td style="text-align:right;">★</td><td>The LAUNCH banner + ring is acknowledgement of launch; the visual register is identical to cruise. No worm&#39;s-eye, no long-lens track, no cathedral framing.</td></tr><tr><td>Cruise</td><td style="text-align:right;">★★</td><td>Cruise is rendered as a continuous slow track — the right base. But there are no held holds, no &quot;Tarkovsky 10% boredom&quot; beats. The cruise is treated as connective tissue between flybys rather than as the body of the mission.</td></tr><tr><td>Mid-cruise event (TCM)</td><td style="text-align:right;">★</td><td>TCM events are listed in the timeline but get no cinematic register — no thruster close-up, no diagrammatic match-cut.</td></tr><tr><td>Flyby approach</td><td style="text-align:right;">★★</td><td>The auto-zoom builds up. Acceleration of cut frequency is absent because there are no cuts.</td></tr><tr><td>Flyby peak</td><td style="text-align:right;">★★</td><td>The composition itself is right (post polish wave 2). The 6–10 second held shot the creative guide calls for is absent — the camera is still lerping during peak.</td></tr><tr><td>Flyby departure</td><td style="text-align:right;">★</td><td>The pull-out exists mechanically. The slow afterglow beat (Cassini&#39;s 12-second silent pull-back) is absent.</td></tr><tr><td>Arrival / orbit insertion</td><td style="text-align:right;">★★★</td><td>Post polish wave 2 — Saturn arrival now frames as orbital docked. Good.</td></tr><tr><td>Landing / surface contact</td><td style="text-align:right;">✗</td><td>/fly hands off to /mars or /moon at landing; no in-/fly landing grammar. POV through the lander&#39;s eye, ECU on landing gear, tilt-up — all absent in /fly.</td></tr><tr><td>End of mission</td><td style="text-align:right;">★</td><td>The arrived state holds the orbital framing now. The locked-off &quot;12-second silent goodbye&quot; isn&#39;t a thing — the camera keeps lerping breathing motion.</td></tr></tbody></table><p><strong>Gap of the section:</strong> four of the ten beats are absent (pre-launch, mid-cruise event, landing, end-of-mission as a distinct held shot) and the remaining six all suffer from the same root problem — there is no concept of a HELD shot. The hero moments arrive, the camera keeps moving, the moment passes.</p><h3 id="§6-reference-matrix" tabindex="-1">§6 Reference matrix <a class="header-anchor" href="#§6-reference-matrix" aria-label="Permalink to &quot;§6 Reference matrix&quot;">​</a></h3><p>We are not currently aiming at any specific shot from the matrix as a deliberate target. The Cassini Grand Finale pull-out, the Earthrise, the Cowboy Bebop Jupiter Gate frame — none of these have a /fly counterpart shot we&#39;ve intentionally built. The closest thing is the limb-grazing Saturn composition (cd0c44295) inspired by Wernquist&#39;s illustrations, but it is general — not a specific named shot.</p><p><strong>Gap of the section:</strong> zero deliberate references. The polish-wave post commits gesture at the matrix but never select a specific entry and engineer the shot to match it.</p><h3 id="§7-pacing-rhythm" tabindex="-1">§7 Pacing &amp; rhythm <a class="header-anchor" href="#§7-pacing-rhythm" aria-label="Permalink to &quot;§7 Pacing &amp; rhythm&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Principle</th><th style="text-align:right;">Score</th><th>Notes</th></tr></thead><tbody><tr><td>Shot duration as emotional weight</td><td style="text-align:right;">✗</td><td>The notion of a shot doesn&#39;t exist; we have one continuous camera, no edit.</td></tr><tr><td>Silent hold</td><td style="text-align:right;">✗</td><td>No holds.</td></tr><tr><td>Cut-on-action</td><td style="text-align:right;">✗</td><td>No cuts.</td></tr><tr><td>1.5× / 2× / 3× escalation</td><td style="text-align:right;">✗</td><td>Pacing isn&#39;t structured as escalation; it&#39;s structured as sim-day rate.</td></tr><tr><td>Afterglow beat</td><td style="text-align:right;">✗</td><td>Camera lerps directly into the next composition.</td></tr><tr><td>Music-as-scaffold</td><td style="text-align:right;">✗</td><td>Episode audio plays as narration, not as cinematic score. There&#39;s no edited rhythm.</td></tr><tr><td>Match-cut graphic continuity</td><td style="text-align:right;">✗</td><td>No cuts → no match cuts.</td></tr><tr><td>Negative space</td><td style="text-align:right;">★</td><td>Flyby peak has good negative space when overlays auto-hide; cruise has it most of the time; mid-cruise it sometimes piles up (FD banner + HUD + capcom + scrubber + timeline).</td></tr></tbody></table><p><strong>Gap of the section:</strong> pacing is sim-time driven, not edit driven. This is the single biggest creative gap.</p><h3 id="§8-dramaturgy-of-mission-events" tabindex="-1">§8 Dramaturgy of mission events <a class="header-anchor" href="#§8-dramaturgy-of-mission-events" aria-label="Permalink to &quot;§8 Dramaturgy of mission events&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Act</th><th style="text-align:right;">Score</th><th>Notes</th></tr></thead><tbody><tr><td>Setup (planning, team)</td><td style="text-align:right;">✗</td><td>We have no pre-mission setup register at all. Mission cards on /missions stand in.</td></tr><tr><td>Inciting incident (launch)</td><td style="text-align:right;">★</td><td>Treated as a beat (banner, ring) but not as a religious cathedral moment.</td></tr><tr><td>Rising action (cruise)</td><td style="text-align:right;">★★</td><td>Patient continuous cruise IS rising action. But no editing rhythm to give it structure.</td></tr><tr><td>Hero moments (flybys)</td><td style="text-align:right;">★★★</td><td>Each flyby cinema is a hero beat. The strongest part of the system.</td></tr><tr><td>Climax (arrival)</td><td style="text-align:right;">★★</td><td>OI cinema is the climax. Post polish wave 2 it composes correctly. The climax-as-act (multi-day cinematic prologue) doesn&#39;t exist.</td></tr><tr><td>Falling action (extended mission)</td><td style="text-align:right;">✗</td><td>Once &quot;arrived&quot; we stop. No extended-mission register.</td></tr><tr><td>Resolution (end of mission)</td><td style="text-align:right;">★</td><td>We hold the arrived framing. The locked-off finale + silence isn&#39;t there.</td></tr></tbody></table><p><strong>Gap of the section:</strong> missions are treated as launch-cruise-arrive, not as setup-incident-rising-hero-climax-falling-resolution. Most of the dramaturgical structure of a real mission is collapsed.</p><h3 id="§9-discipline-of-not-doing-things" tabindex="-1">§9 Discipline of NOT doing things <a class="header-anchor" href="#§9-discipline-of-not-doing-things" aria-label="Permalink to &quot;§9 Discipline of NOT doing things&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Discipline</th><th style="text-align:right;">Score</th><th>Notes</th></tr></thead><tbody><tr><td>Don&#39;t move when stillness is the emotion</td><td style="text-align:right;">✗</td><td>The camera always moves.</td></tr><tr><td>Don&#39;t add music to silence</td><td style="text-align:right;">n/a</td><td>We don&#39;t currently add music. The Cassini Grand Finale would benefit from a deliberate silence here.</td></tr><tr><td>Don&#39;t cut when audience needs to dwell</td><td style="text-align:right;">n/a</td><td>We don&#39;t cut at all.</td></tr><tr><td>Sometimes centre the planet</td><td style="text-align:right;">★</td><td>Centred framing accidentally happens in some compositions. Not deliberately invoked for sacred-subject moments.</td></tr><tr><td>Don&#39;t add foreground when planet is the subject</td><td style="text-align:right;">★</td><td>Sometimes the ship is correctly visible; sometimes it&#39;s a distraction (Earthrise-type beats want NO ship).</td></tr><tr><td>Don&#39;t intercut a hero moment</td><td style="text-align:right;">★</td><td>We don&#39;t intercut because we don&#39;t cut. Accidentally correct.</td></tr><tr><td>Don&#39;t over-orbit</td><td style="text-align:right;">★★★</td><td>We almost never orbit deliberately. Good.</td></tr><tr><td>Don&#39;t over-detail</td><td style="text-align:right;">★★</td><td>Generally clean. Some overlay clutter during transitions (now reduced after wave 2).</td></tr><tr><td>Don&#39;t motion-blur the awe</td><td style="text-align:right;">★★★</td><td>No motion blur applied; lyric shots are precise. Good.</td></tr><tr><td>Don&#39;t apologise for slowness</td><td style="text-align:right;">★</td><td>Mostly we DO move too fast — auto-zoom is brisk; cruise reads as connective tissue. The Tarkovsky 10% boredom budget is unspent.</td></tr></tbody></table><h3 id="§10-meta-question" tabindex="-1">§10 Meta-question <a class="header-anchor" href="#§10-meta-question" aria-label="Permalink to &quot;§10 Meta-question&quot;">​</a></h3><p>Restated: <em>what does this shot KNOW?</em></p><p>Currently a /fly shot at any given moment is the result of:</p><ol><li>Where the spacecraft is on the spline</li><li>What sub-phase that maps to</li><li>What composition lerp-target that sub-phase has</li><li>Where the lerp is right now</li></ol><p>There is no per-shot <strong>thesis</strong>. The framing has reasons, but those reasons are mechanical (track the ship, frame the body limb), not emotional (this is the moment the mission becomes irrevocable; this is the moment we touch the ringed god; this is the moment we say goodbye). The throne-of-glory tier requires a thesis per shot. We have a thesis per <strong>sub-phase</strong> — which is much coarser.</p><hr><h2 id="wave-3-prioritised-plan" tabindex="-1">Wave 3 prioritised plan <a class="header-anchor" href="#wave-3-prioritised-plan" aria-label="Permalink to &quot;Wave 3 prioritised plan&quot;">​</a></h2><p>Selected for impact-per-engineering-cost. Each item is the smallest discrete change that advances the creative-direction guide measurably.</p><h3 id="w3-1-—-add-a-held-shot-mechanism-highest-roi" tabindex="-1">W3.1 — Add a held-shot mechanism (highest ROI) <a class="header-anchor" href="#w3-1-—-add-a-held-shot-mechanism-highest-roi" aria-label="Permalink to &quot;W3.1 — Add a held-shot mechanism (highest ROI)&quot;">​</a></h3><p>The single biggest gap is the absence of any locked-off shot. Add a new sub-phase state: when in the flyby peak window and within ±0.5 days of closest approach, <strong>freeze the camera lerp targets</strong> for 2.5 wall-clock seconds. Camera holds the iconic composition silent and still. The diamond pulses on, the body fills the frame, the ship hangs in foreground — and nothing moves except the slow body rotation underneath. Restores the &quot;discipline of stillness.&quot; References: Cowboy Bebop Jupiter Gate hold; Cassini ring-plane crossing.</p><p><strong>Estimated work:</strong> 1 small block in /fly +page.svelte; ~30 lines.</p><h3 id="w3-2-—-add-an-afterglow-pull-out-beat" tabindex="-1">W3.2 — Add an afterglow pull-out beat <a class="header-anchor" href="#w3-2-—-add-an-afterglow-pull-out-beat" aria-label="Permalink to &quot;W3.2 — Add an afterglow pull-out beat&quot;">​</a></h3><p>Immediately after the peak hold, run a 6-second slow dolly pull-out (not the existing lerp — a dedicated tween with its own ease curve) back to wide. During the pull-out, suppress all overlays (HUD, banner, scrubber). The body recedes; the ship recedes with it; the star field reveals around the frame edges. References: Cassini Grand Finale; Voyager Pale Blue Dot context.</p><p><strong>Estimated work:</strong> moderate — a new tween system + overlay-suppress gate. ~60 lines.</p><h3 id="w3-3-—-pre-launch-sub-phase-cinematic-prologue" tabindex="-1">W3.3 — Pre-launch sub-phase (cinematic prologue) <a class="header-anchor" href="#w3-3-—-pre-launch-sub-phase-cinematic-prologue" aria-label="Permalink to &quot;W3.3 — Pre-launch sub-phase (cinematic prologue)&quot;">​</a></h3><p>Currently /fly starts at met=0 (launch). Add a 4-second pre-launch beat: close static shot on Earth with the launch site visible in the limb, the spacecraft sprite holding off-axis, then the launch ring + banner fire. During this pre-launch beat the scrubber + HUD are hidden. Restores the &quot;ritual / weight of decades of work&quot; register. References: First Man pre-launch; Hidden Figures Glenn ascent.</p><p><strong>Estimated work:</strong> moderate. ~50 lines + a met&lt;0 path through the spacecraft-position calculation.</p><h3 id="w3-4-—-end-of-mission-locked-off-finale" tabindex="-1">W3.4 — End-of-mission locked-off finale <a class="header-anchor" href="#w3-4-—-end-of-mission-locked-off-finale" aria-label="Permalink to &quot;W3.4 — End-of-mission locked-off finale&quot;">​</a></h3><p>For missions that end at a body via OI (Cassini-Saturn, Galileo- Jupiter, etc.), after the arrived-state composition settles, hold for 12 wall-clock seconds with the camera locked. Suppress all overlays except a small &quot;MISSION END&quot; caption that fades in around second 8. Fade to black at second 12. References: Cassini Grand Finale; 2001 starchild; Wernquist&#39;s &quot;Where the Mission Ends&quot; animation.</p><p><strong>Estimated work:</strong> small. ~40 lines + a fade-to-black overlay.</p><h3 id="w3-5-—-selective-ui-suppression-during-the-peak-hold" tabindex="-1">W3.5 — Selective UI suppression during the peak hold <a class="header-anchor" href="#w3-5-—-selective-ui-suppression-during-the-peak-hold" aria-label="Permalink to &quot;W3.5 — Selective UI suppression during the peak hold&quot;">​</a></h3><p>The peak-hold beat (W3.1) needs negative-space discipline. While the camera is in the held-shot state, suppress: FlightDirectorBanner, ConicSectionPanel, the scrubber-row, the active-event HUD row, and the milestone diamonds (not the actively pulsing one). What remains: the ship + the body + the star field. The &quot;don&#39;t add foreground when the planet is the subject&quot; discipline.</p><p><strong>Estimated work:</strong> small. CSS + a single <code>peakHeld</code> state.</p><h3 id="w3-6-—-cassini-day-the-earth-smiled-reference-shot" tabindex="-1">W3.6 — Cassini &quot;Day the Earth Smiled&quot; reference shot <a class="header-anchor" href="#w3-6-—-cassini-day-the-earth-smiled-reference-shot" aria-label="Permalink to &quot;W3.6 — Cassini &quot;Day the Earth Smiled&quot; reference shot&quot;">​</a></h3><p>Pick one specific reference matrix entry and engineer the /fly path to land exactly on it. For Cassini, that&#39;s the &quot;Day the Earth Smiled&quot; composite — Saturn backlit, Earth as a pixel in the rings. Engineer the mission&#39;s specific Saturn-flyby cinema to compose this exact shot: Saturn fills 70% of frame, sun directly behind, ring system in silhouette, with a hidden Earth indicator at the ring-gap-pixel. References: Carolyn Porco / Cassini ISS 2013.</p><p><strong>Estimated work:</strong> moderate. Per-mission cinema override.</p><h3 id="w3-7-—-trans-planetary-scrubber-jump-as-a-deliberate-cut" tabindex="-1">W3.7 — Trans-planetary scrubber-jump as a deliberate cut <a class="header-anchor" href="#w3-7-—-trans-planetary-scrubber-jump-as-a-deliberate-cut" aria-label="Permalink to &quot;W3.7 — Trans-planetary scrubber-jump as a deliberate cut&quot;">​</a></h3><p>When the user scrubs across the timeline by more than 1 mission year (Jupiter → Earth on Cassini), treat it as a cinematic cut: fade to black for 200 ms, fade in with the new composition pre-lerped to its target (don&#39;t re-lerp from the old position). The audience reads this as a real edit, not a long lerp. The first deliberate cut in /fly.</p><p><strong>Estimated work:</strong> small. ~30 lines on the jumpToMet path.</p><h3 id="w3-8-—-tarkovsky-cruise-—-10-second-held-cruise-beat" tabindex="-1">W3.8 — Tarkovsky cruise — 10-second held cruise beat <a class="header-anchor" href="#w3-8-—-tarkovsky-cruise-—-10-second-held-cruise-beat" aria-label="Permalink to &quot;W3.8 — Tarkovsky cruise — 10-second held cruise beat&quot;">​</a></h3><p>Once per mission, during the longest cruise segment, hold the camera locked on a profile of the ship for 10 wall-clock seconds. The body of the mission, given dignity. The audience falls into the rhythm. References: 2001 Discovery cruise; Ad Astra Neptune solo cruise.</p><p><strong>Estimated work:</strong> small. Cruise lerp gate.</p><hr><h2 id="what-s-deliberately-deferred-to-a-later-wave" tabindex="-1">What&#39;s deliberately deferred to a later wave <a class="header-anchor" href="#what-s-deliberately-deferred-to-a-later-wave" aria-label="Permalink to &quot;What&#39;s deliberately deferred to a later wave&quot;">​</a></h2><ul><li>Per-shot music/score (out of scope without an audio system)</li><li>Match-cut graphic continuity (requires cut grammar first; do W3.7 to get the first cut, then build on it)</li><li>Full pre-launch ritual (W3.3 is the minimal version; expanding to the Hidden-Figures-style mission-control intercut would need new scene content)</li><li>POV / cockpit shots for landings (the landing routes /mars + /moon could absorb these separately)</li></ul><hr><h2 id="verdict" tabindex="-1">Verdict <a class="header-anchor" href="#verdict" aria-label="Permalink to &quot;Verdict&quot;">​</a></h2><p>The technical fly-cinematic-gap-analysis (wave-2 plan) closed almost all the rendering gaps. The creative fly-cinematic-gap-analysis (this doc) reveals that the <strong>directorial</strong> gaps are largely untouched: there are no held shots, no cuts, no afterglow beats, no pacing structure.</p><p>Polish wave 2 made every shot in /fly look correct. Polish wave 3 needs to make every shot in /fly mean something. The order of operations matters: W3.1 (peak hold) is the single change that does the most directional work — it introduces the discipline of stillness, which then unlocks W3.2 (afterglow pull-out), W3.4 (locked-off finale), and W3.8 (Tarkovsky cruise hold). All four are variations of the same core mechanism.</p><p>Starts with the hold.</p>',72)])])}const m=e(s,[["render",o]]);export{g as __pageData,m as default};
